//! PE-image inspection and compatibility-state RTL routines.
use core::sync::atomic::{AtomicU32,AtomicU8,Ordering};
const SUCCESS:i32=0;const INVALID:i32=0xC000000Du32 as i32;const SMALL:i32=0xC0000023u32 as i32;
#[repr(C)] pub struct RtlVersionInfoExW{pub size:u32,pub major:u32,pub minor:u32,pub build:u32,pub platform:u32,pub service_pack:[u16;128],pub service_pack_major:u16,pub service_pack_minor:u16,pub suite_mask:u16,pub product_type:u8,pub reserved:u8}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_image_nt_header(base:*const u8)->*mut u8{if base.is_null()||unsafe{*(base as *const u16)}!=0x5a4d{return core::ptr::null_mut();}let off=unsafe{*(base.add(0x3c) as *const u32)} as usize;if off>16*1024*1024{return core::ptr::null_mut();}let p=unsafe{base.add(off)};if unsafe{*(p as *const u32)}!=0x00004550{return core::ptr::null_mut();}p as *mut u8}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_image_nt_header_ex(flags:u32,base:*const u8,size:u64,out:*mut *mut u8)->i32{if out.is_null()||base.is_null()||flags&!3!=0{return INVALID;}unsafe{*out=core::ptr::null_mut();}if size<64||unsafe{*(base as *const u16)}!=0x5a4d{return INVALID;}let off=unsafe{*(base.add(0x3c) as *const u32)} as u64;if off.checked_add(24).is_none_or(|x|x>size){return INVALID;}let p=unsafe{base.add(off as usize)};if unsafe{*(p as *const u32)}!=0x00004550{return INVALID;}let opt_size=unsafe{*(p.add(20) as *const u16)} as u64;if off+24+opt_size>size{return INVALID;}unsafe{*out=p as *mut u8;}SUCCESS}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_image_directory_entry_to_data(base:*const u8,mapped:u8,index:u16,size_out:*mut u32)->*mut u8{if base.is_null()||size_out.is_null(){return core::ptr::null_mut();}unsafe{*size_out=0;}let nt=unsafe{rtl_image_nt_header(base)};if nt.is_null(){return core::ptr::null_mut();}let opt=unsafe{nt.add(24)};let magic=unsafe{*(opt as *const u16)};let (num_off,dir_off)=if magic==0x20b{(108usize,112usize)}else if magic==0x10b{(92,96)}else{return core::ptr::null_mut();};let n=unsafe{*(opt.add(num_off) as *const u32)};if index as u32>=n||index>=16{return core::ptr::null_mut();}let ent=unsafe{opt.add(dir_off+index as usize*8)};let rva=unsafe{*(ent as *const u32)};let sz=unsafe{*(ent.add(4) as *const u32)};if rva==0||sz==0{return core::ptr::null_mut();}unsafe{*size_out=sz;}if mapped!=0{return unsafe{base.add(rva as usize) as *mut u8};}let sections=unsafe{nt.add(24+*(nt.add(20) as *const u16) as usize)};let count=unsafe{*(nt.add(6) as *const u16)} as usize;for i in 0..count{let sh=unsafe{sections.add(i*40)};let virtual_size=unsafe{*(sh.add(8) as *const u32)};let virtual_address=unsafe{*(sh.add(12) as *const u32)};let raw_size=unsafe{*(sh.add(16) as *const u32)};let raw_ptr=unsafe{*(sh.add(20) as *const u32)};if rva>=virtual_address&&rva<virtual_address.saturating_add(virtual_size.max(raw_size)){let delta=rva-virtual_address;if delta>=raw_size{return core::ptr::null_mut();}return unsafe{base.add((raw_ptr+delta) as usize) as *mut u8};}}core::ptr::null_mut()}
fn cmp(v:u64,refv:u64,cond:u32)->bool{match cond{1=>v<refv,2=>v==refv,3=>v<=refv,4=>v>refv,5=>v!=refv,6=>v>=refv,_=>false}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_verify_version_info(info:*const RtlVersionInfoExW,type_mask:u32,condition_mask:u64)->i32{if info.is_null(){return INVALID;}let x=unsafe{&*info};let fields=[(0x1u32,0u64,x.minor as u64,0u32),(0x2,10,x.major as u64,1),(0x4,26100,x.build as u64,2),(0x8,2,x.platform as u64,3),(0x10,0,x.service_pack_minor as u64,4),(0x20,0,x.service_pack_major as u64,5),(0x40,0,x.suite_mask as u64,6),(0x80,1,x.product_type as u64,7)];for (bit,current,requested,slot) in fields{if type_mask&bit!=0{let cond=((condition_mask>>(slot*3))&7) as u32;if !cmp(current,requested,cond){return 0xC0000059u32 as i32;}}}SUCCESS}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_is_generic_table_empty(table:*const core::ffi::c_void)->u8{if table.is_null(){return 1;} (unsafe{*(table as *const usize)}==0) as u8}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_is_generic_table_empty_avl(table:*const core::ffi::c_void)->u8{if table.is_null(){return 1;} (unsafe{*(table as *const usize)}==0) as u8}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_number_generic_table_elements(table:*const core::ffi::c_void)->u32{if table.is_null(){return 0;}unsafe{*(table.cast::<u8>().add(36) as *const u32)}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_number_generic_table_elements_avl(table:*const core::ffi::c_void)->u32{if table.is_null(){return 0;}unsafe{*(table.cast::<u8>().add(20) as *const u32)}}
pub(super) static PORTABLE:AtomicU8=AtomicU8::new(0);
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_set_portable_operating_system(v:u8){PORTABLE.store((v!=0) as u8,Ordering::Release);}
static CONSOLE_PID:AtomicU32=AtomicU32::new(0);
static SYSTEM_ROOT:[u16;12]=[92,83,121,115,116,101,109,82,111,111,116,0];
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_set_console_session_foreground_process_id(pid:u32){CONSOLE_PID.store(pid,Ordering::Release);}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_get_console_session_foreground_process_id()->u32{CONSOLE_PID.load(Ordering::Acquire)}
static PROCESS_PLACEHOLDER:AtomicU8=AtomicU8::new(0);
static THREAD_PLACEHOLDER:AtomicU8=AtomicU8::new(0);
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_set_process_placeholder_compatibility_mode(mode:u8)->u8{PROCESS_PLACEHOLDER.swap(mode,Ordering::AcqRel)}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_query_process_placeholder_compatibility_mode()->u8{PROCESS_PLACEHOLDER.load(Ordering::Acquire)}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_set_thread_placeholder_compatibility_mode(mode:u8)->u8{THREAD_PLACEHOLDER.swap(mode,Ordering::AcqRel)}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_query_thread_placeholder_compatibility_mode()->u8{THREAD_PLACEHOLDER.load(Ordering::Acquire)}

#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_get_nt_system_root()->*const u16{SYSTEM_ROOT.as_ptr()}
